python3 - <<'PY'
p='src/types/checker/functions/call_validation.rs'
s=open(p).read()
old = """        match &arg.kind {
            ExprKind::Variable(_) => Ok(true),
            ExprKind::ArrayAccess { array, .. } if matches!(array.kind, ExprKind::Variable(_)) => {
                Ok(matches!(
                    self.infer_type(array, env)?.codegen_repr(),
                    PhpType::Array(_)
                ))
            }
            _ => Ok(false),
        }
    }"""
new = """        match &arg.kind {
            ExprKind::Variable(_) => Ok(true),
            ExprKind::ArrayAccess { array, .. } if matches!(array.kind, ExprKind::Variable(_)) => {
                Ok(matches!(
                    self.infer_type(array, env)?.codegen_repr(),
                    PhpType::Array(_)
                ))
            }
            // A PROPERTY is a writable place in php — `sort($obj->items)` and
            // `bump($this->rows)` are ordinary code — and `ir_lower::expr::ref_place_args`
            // lowers one by reading it into a hidden temporary, calling with that, and writing
            // the temporary back. It can only do that for ARRAY storage, so this accepts
            // exactly what it can lower: a scalar property keeps the existing diagnostic rather
            // than compiling into a write-back that never happens.
            ExprKind::PropertyAccess { .. } | ExprKind::StaticPropertyAccess { .. } => {
                Ok(matches!(
                    self.infer_type(arg, env)?.codegen_repr(),
                    PhpType::Array(_) | PhpType::AssocArray { .. }
                ))
            }
            _ => Ok(false),
        }
    }"""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))

p2='src/ir_lower/expr/ref_place_args.rs'
s2=open(p2).read()
old2 = """    if !prefer_extension
        && (ctx.functions.contains_key(canonical) || ctx.extern_functions.contains_key(canonical))
    {
        // User-defined and extern callees own a separate by-reference machine that already
        // rejects non-local arguments with a named diagnostic.
        return None;
    }"""
new2 = """    if !prefer_extension && ctx.extern_functions.contains_key(canonical) {
        // An EXTERN (C ABI) callee takes a raw pointer, not a php reference cell, so the
        // read/call/write-back rewrite has nothing to write back through.
        return None;
    }"""
assert s2.count(old2)==1
open(p2,'w').write(s2.replace(old2,new2))
print('property by-ref accepted in checker and lowering')
